ect		,\bakuba\kernel\objects\DwCallBack $onConnect		,\bakuba\kernel\network\DwPort $dwPort		,int $protocole = \SOL_TCP	) {		$dwIp = $dwPort->getIp();		$dwCIDR = $dwIp->getDwCIDR();		$this->dwInterface = $dwCIDR->getDwInterface();				$this->dwPort=$dwPort;				switch( $protocole ) {			case \SOL_TCP :				$this->sock_type=\SOCK_STREAM;				break;			case \SOL_UDP :				$this->sock_type=\SOCK_DGRAM;				//$this->sock_type=\SOCK_SEQPACKET;				break;			default :				throw new \Exception("unknow protocole:$protocole");				break;		}				$localSslCert = \bakuba\kernel\agartha\DwInstall::getLocalDirectory( '/etc/darksrv/ssl/darkweb.fr' );		$this->sslContext = \stream_context_create( [			'ssl' => [				'local_cert'        => "{$localSslCert}/darkweb.fr-full.pem"				,'local_pk'         => "{$localSslCert}/darkweb.fr.key" // si séparée//				,'passphrase'        => 'motdepasse' // si clé chiffrée				,'verify_peer'       => false // en test (oui mais bakuba c'est du prod/test en live ;) )				,'allow_self_signed' => true  // en test (oui mais bakuba c'est du prod/test en live ;) )//				,'SNI_server_name'   => 'ton-domaine.dev' // optionnel, SNI			]		] );		parent::__construct( $dwStreamSelect ,$onConnect );//,$dwPort ,$protocole );	}		public function init(  ) : void {		$this->listenSock( );		//parent::init();	}	protected $isListen = false;	protected function listenSock( ) {		if ( $this->isListen )			throw new \Exception("is ever in listen");		else {			$this->listen();			$this->isListen = true;		}	}	protected function createDwStreamSocket( $sock ) : DwStreamSocket {		return new DwStreamSocket(			$this			,$this->dwInterface			,$sock		);		/*		 $dwStreamSocket =  new DwStreamSocket( $this ,$dwInterface ,$sock );		 $dwStreamSocket->enableSocketFullTrace();		 return $dwStreamSocket;		//*/	}	// dwItemContainer : DwSocketServerMonoThread(item) => DwServer(item) => DwBakuba(item) => DwNode(item) => DwAgartha(map)	protected function listen( string $srvUri = null ) : bool {		$return = false;		$dwIp = $this->dwPort->getIp();		if ( \bakuba\kernel\network\DwIp6::getStaticClassName() == $dwIp->getClassName() )			$ipAdress = "[{$dwIp->getIpAddress()}]";		else			$ipAdress = $dwIp->getIpAddress();		$port=$this->dwPort->getPort();		if ( \is_null( $srvUri ) ) $srvUri = ( $this->sock_type != \SOCK_DGRAM ? "tcp" : "udp" )."://{$ipAdress}:$port";				$this->log->trace( $srvUri );		$sock = \stream_socket_server(			$srvUri			,$errno			,$errstr			,$this->sock_type != \SOCK_DGRAM ? ( STREAM_SERVER_BIND | STREAM_SERVER_LISTEN ) : \STREAM_SERVER_BIND 			,$this->sslContext		);				if ( $sock == false ) {			throw new \Exception(				"failed to stream_socket_server[{$errno}]: {$errstr}"			);		} else {			\stream_set_blocking( $sock , false);			$iDwLogger = null;			if ( \method_exists( $this->log ,"upTo" ) )				$iDwLogger = $this->log->upTo( $this ,"listen" );			else				$iDwLogger = $this->log;						//$iDwLogger->trace("listen");			//$this->dwPort->setDebug( $iDwLogger );						$dwStreamSocket = $this->createDwStreamSocket( $sock );			$dwStreamSocket->listenTo( $this->dwPort );			//$this->getDwStreamSelect()->setSocketLimiteDeltaTimer( 0.25 );			$dwStreamSocket->setOnReaded( new DwCallBack( array( &$this ,"acceptStreamSocketConnection" ) ,$dwStreamSocket ) );			$this->getDwStreamSelect()->streamSocketRead( $dwStreamSocket );			$return = true;			$this->log->debug("[{$ipAdress}]:{$port} -listen");		}		return $return;	}	private $peers = array();	public function acceptStreamSocketConnection( DwStreamSocket $dwSocketAccept ) : void {		$this->log->trace(".");		if ( $this->sock_type != \SOCK_DGRAM )			$this->acceptTcpConnection( $dwSocketAccept );		else {			$dwSocketRead = $this->createDwStreamSocket( $dwSocketAccept->getResource() );			$dwSocketRead->noSocketClose();			$this->newStreamSocketConnection( $dwSocketRead );		}		$this->getDwStreamSelect()->streamSocketRead( $dwSocketAccept );	}	public function acceptTcpConnection( DwStreamSocket $dwStreamSocketAccept ) : void {		$this->log->trace(".");		$sockListen = $dwStreamSocketAccept->getResource();		$sock = @\stream_socket_accept( $sockListen );		if ( $sock === false )			$this->log->warn( "no connexion(sock:false) to stream_socket_accept" );		elseif ( $sock !== null ) {			$dwStreamSocket = $this->createDwStreamSocket( $sock );			$dwStreamSocket->connectedReadPeer();			$this->newConnection( $dwStreamSocket );				//$iDwLogger->debug("run go in the action, john");		} else 			throw new \Exception( "failed to socket_accept sock not false but null" );	}	protected function streamSocketIpConnexion( DwStreamSocket $dwStreamSocket ) : DwStreamSocketIpConnexion {		return new \bakuba\kernel\io\stream\DwStreamSocketIpConnexion (			$this->getDwStreamSelect()			,$dwStreamSocket			,$this->dwPort			,$dwStreamSocket->getDwPort()		);	}	public function newStreamSocketConnection( DwStreamSocket $dwStreamSocket ) : void {		$this->log->info( " Try StreamSocket" );		$this->dwResourceSelect->getDwObjectTimer()->addTick(			$this->onConnect->getClone( $this->streamSocketIpConnexion( $dwStreamSocket ) )		);	}		///*	public function __destruct() {		//$this->log->trace( "." );		parent::__destruct();		foreach( $this as $key => $toDestruct )			if ( isset( $this->$key ) ) 				unset( $this->$key );	}	//*/	public function getClassName( bool $fqcn=null ) : string {		return self::getStaticClassName( $fqcn );	}	public static function getStaticClassName( bool $fqcn=null ) : string {		return $fqcn ? parent::getStaticClassName( $fqcn ).self::CLASS_SEPARATOR.__CLASS__ : __CLASS__;	}}?>